    def masscenter(cells): return sum(r for r,c in cells)/len(cells), sum(c for r,c in cells)/len(cells)
    for obj in comps(gi):
        rs={r for r,c in obj}; cs={c for r,c in obj}
        B={(r,c) for r in range(min(rs),max(rs)+1) for c in range(min(cs),max(cs)+1)}
        h=B-set(obj)
