        hole=list(h)[0]
        mr,mc=masscenter(obj)
        dr=hole[0]-mr; dc=hole[1]-mc
        # direction: away from mass -> sign(dr)*sign(dc)... use vector from center to hole
        sgn=(np.sign(dr),np.sign(dc))
        step=(1 if sgn[0]==1 else -1, 1 if sgn[1]==1 else -1)
        rr,cc=hole
