        for _ in range(max(1,H*W)):
            nr,nc=rr+step[0], cc+step[1]
            if 0<=nr<H and 0<=nc<W:
                if gi[nr,nc]==0:
                    res[nr][nc]=col; rr,nc=nr,nc
                else: break
            else: break
    return res
