def dihedral(n):
    res={tuple(n)}; cur=[tuple(n)]
    for _ in range(3):
        nxt=set()
        for x in cur:
            nx=tuple(sorted((b,-a) for a,b in list(x))); ny=tuple(sorted((b,a) for a,b in list(x)))
            nxt.update([nx,ny])
        cur=list(nxt)
        res|=set(map(tuple,nxt))
    return res
