def solve(inp):
    H=len(inp);W=len(inp[0])
    cnt=Counter(v for r in inp for v in r)
    bgv=cnt.most_common(1)[0][0]
    def comps(g,c):
        seen=set();out=[]
        for i in range(H):
            for j in range(W):
                if g[i][j]==c and (i,j) not in seen:
                    q={(i,j)};seen.add((i,j));s=set()
                    while q:
                        a,b=q.pop();s.add((a,b))
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            p=(a+da,b+db)
                            if 0<=p[0]<H and 0<=p[1]<W and g[p[0]][p[1]]==c and p not in seen:
                                seen.add(p);q.add(p)
                    out.append(s)
        return out
    out=[row[:] for row in inp]
    for c in sorted(set(v for r in inp for v in r)-{bgv}):
        for blob in comps(inp,c):
            # corner: cell adjacent to 2 orthogonal blob cells
            cor=None
            for p in blob:
                nb=[(a+da,b+db) for a,b in [p] for da,db in ((1,0),(-1,0),(0,1),(0,-1))]
                if sum(n in blob for n in nb)==2: cor=p
            dr={ (cor[0]+d,cor[1])+e for d,e in []}
            # arms
            xs=[(p[0]-cor[0],p[1]-cor[1]) for p in blob-p if (p[0]-cor[0])**2+(p[1]-cor[1])**2==1]
            dirs={}
